public class RecursionBasics {
    static int sumTo(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n == 0) {
            return 0;
        }
        return n + sumTo(n - 1);
    }

    static int sumToWithTrace(int n, StringBuilder trace) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        trace.append("enter ").append(n).append('\n');
        if (n == 0) {
            trace.append("return 0\n");
            return 0;
        }
        int result = n + sumToWithTrace(n - 1, trace);
        trace.append("return ").append(result).append('\n');
        return result;
    }

    static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw error;
        }
        throw new AssertionError("expected " + type.getSimpleName());
    }

    public static void main(String[] args) {
        assert sumTo(0) == 0;
        assert sumTo(1) == 1;
        assert sumTo(4) == 10;
        expect(IllegalArgumentException.class, () -> sumTo(-1));

        StringBuilder trace = new StringBuilder();
        assert sumToWithTrace(3, trace) == 6;
        String expected = "enter 3\nenter 2\nenter 1\nenter 0\n"
                + "return 0\nreturn 1\nreturn 3\nreturn 6\n";
        assert trace.toString().equals(expected) : trace;
        System.out.println("recursion-basics checks: OK");
    }
}
